-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('LS', 'Lesotho')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'LS', null, 'Lesotho', 'Country', 1, 'lesotho', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (10 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'LS', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('lesotho', 'Berea District', 'District', 2, 'lesotho/berea-district', 0),
    ('lesotho', 'Butha-Buthe District', 'District', 2, 'lesotho/butha-buthe-district', 1),
    ('lesotho', 'Leribe District', 'District', 2, 'lesotho/leribe-district', 2),
    ('lesotho', 'Mafeteng District', 'District', 2, 'lesotho/mafeteng-district', 3),
    ('lesotho', 'Maseru District', 'District', 2, 'lesotho/maseru-district', 4),
    ('lesotho', 'Mohale''s Hoek District', 'District', 2, 'lesotho/mohale-s-hoek-district', 5),
