    ('lesotho', 'Thaba-Tseka District', 'District', 2, 'lesotho/thaba-tseka-district', 9)
) as v(parent_path, name, location_type, level, path, sort_order)
join public.locations p
  on p.country_code = 'LS' and p.path = v.parent_path
